// Package transport provides predefined transport protocol.
package transport

// Protocol indicates the transport protocol.
type Protocol int

// Predefined transport protocols.
const (
	PurePayload Protocol = 0

	TTHeader  Protocol = 1 << iota // 2
	Framed                          // 4
	HTTP                            // 8
	GRPC                            // 16
	HESSIAN2                        // 32
	_                               // 64 reserved (was STREAMING)
	TTHeaderStreaming Protocol = 64 // dedicated flag
	GRPCStreaming     Protocol = 128

	TTHeaderFramed = TTHeader | Framed
)

// Unknown indicates the protocol is unknown.
const Unknown = "Unknown"

// String prints human readable information.
func (tp Protocol) String() string {
	if tp == PurePayload {
		return "PurePayload"
	}

	// Individual flags
	flags := []struct {
		value Protocol
		name  string
	}{
		{TTHeader, "TTHeader"},
		{Framed, "Framed"},
		{HTTP, "HTTP"},
		{GRPC, "GRPC"},
		{HESSIAN2, "Hessian2"},
		{TTHeaderStreaming, "TTHeaderStreaming"},
		{GRPCStreaming, "GRPCStreaming"},
	}

	// Check for exact single flag match first
	for _, flag := range flags {
		if tp == flag.value {
			return flag.name
		}
	}

	// Composite value: collect all set flags in ascending bit order
	var parts []string
	for _, flag := range flags {
		if tp&flag.value != 0 {
			parts = append(parts, flag.name)
		}
	}

	if len(parts) == 0 {
		return Unknown
	}

	// Join with pipe separator
	result := parts[0]
	for i := 1; i < len(parts); i++ {
		result += "|" + parts[i]
	}
	return result
}
