// Header represents streaming metadata headers.
type Header map[string]string

// Trailer represents streaming metadata trailers.
type Trailer map[string]string

// ClientStream defines the typed client-side streaming interface.
type ClientStream[Req, Resp any] interface {
	// Context returns the stream context.
	Context() context.Context

	// Send sends a request message to the server.
	Send(req *Req) error

	// Recv receives a response message from the server.
	Recv(resp *Resp) error

	// Close closes the send direction of the stream.
	Close() error

	// Header retrieves the header metadata from the server.
	Header() (Header, error)

	// Trailer retrieves the trailer metadata from the server.
	Trailer() Trailer
}

// ServerStream defines the typed server-side streaming interface.
type ServerStream[Req, Resp any] interface {
	// Context returns the stream context.
	Context() context.Context

	// Recv receives a request message from the client.
	Recv(req *Req) error

	// Send sends a response message to the client.
	Send(resp *Resp) error

	// SetHeader sets the header metadata.
	SetHeader(header Header) error

	// SetTrailer sets the trailer metadata.
	SetTrailer(trailer Trailer)
}

// ClientStreamWrapper wraps an untyped Stream into a typed ClientStream.
type ClientStreamWrapper[Req, Resp any] struct {
	stream Stream
}

// NewClientStreamWrapper creates a new ClientStreamWrapper.
func NewClientStreamWrapper[Req, Resp any](stream Stream) ClientStream[Req, Resp] {
	return &ClientStreamWrapper[Req, Resp]{stream: stream}
}

func (w *ClientStreamWrapper[Req, Resp]) Context() context.Context {
	return w.stream.Context()
}

func (w *ClientStreamWrapper[Req, Resp]) Send(req *Req) error {
	return w.stream.SendMsg(req)
}

func (w *ClientStreamWrapper[Req, Resp]) Recv(resp *Resp) error {
	return w.stream.RecvMsg(resp)
}

func (w *ClientStreamWrapper[Req, Resp]) Close() error {
	return w.stream.Close()
}

func (w *ClientStreamWrapper[Req, Resp]) Header() (Header, error) {
	hdr := w.stream.Header()
	return Header(hdr), nil
}

func (w *ClientStreamWrapper[Req, Resp]) Trailer() Trailer {
	return Trailer(w.stream.Trailer())
}

