package streaming

import (
	"context"

	"github.com/cloudwego/kitex/pkg/remote/trans/nphttp2/metadata"
)

// Header represents streaming metadata headers.
type Header = metadata.MD

// Trailer represents streaming metadata trailers.
type Trailer = metadata.MD

// ================== Untyped Base Interfaces ==================

// ClientStream is the untyped base interface for client-side streaming.
type ClientStream interface {
	// SendMsg sends a message to the server.
	SendMsg(ctx context.Context, m any) error
	// RecvMsg receives a message from the server.
	RecvMsg(ctx context.Context, m any) error
	// Header returns the header metadata from the server.
	Header() (Header, error)
	// Trailer returns the trailer metadata from the server.
	Trailer() Trailer
	// CloseSend closes the send direction of the stream.
	CloseSend(ctx context.Context) error
	// Context returns the context associated with the stream.
	Context() context.Context
}

// ServerStream is the untyped base interface for server-side streaming.
type ServerStream interface {
	// SendMsg sends a message to the client.
	SendMsg(ctx context.Context, m any) error
	// RecvMsg receives a message from the client.
	RecvMsg(ctx context.Context, m any) error
	// SetHeader sets the header metadata to send to the client.
	SetHeader(hd Header) error
	// SendHeader sends the header metadata immediately.
	SendHeader(hd Header) error
	// SetTrailer sets the trailer metadata to send to the client.
	SetTrailer(hd Trailer)
}

// ================== Generic Client Interfaces ==================

// ServerStreamingClient is the client-side interface for server streaming calls.
// The server sends multiple responses for a single request.
type ServerStreamingClient[Res any] interface {
	ClientStream
	// Recv receives a typed response from the server.
	Recv(ctx context.Context) (*Res, error)
}

// ClientStreamingClient is the client-side interface for client streaming calls.
// The client sends multiple requests and receives a single response.
type ClientStreamingClient[Req any] interface {
	ClientStream
	// Send sends a typed request to the server.
	Send(ctx context.Context, req *Req) error
}

// BidiStreamingClient is the client-side interface for bidirectional streaming calls.
// Both client and server can send multiple messages.
type BidiStreamingClient[Req, Res any] interface {
	ClientStream
	// Send sends a typed request to the server.
	Send(ctx context.Context, req *Req) error
	// Recv receives a typed response from the server.
	Recv(ctx context.Context) (*Res, error)
}

// UnaryClient is the client-side interface for unary calls (single request/response).
type UnaryClient[Req, Res any] interface {
	ClientStream
	// Invoke performs a unary call with typed request and response.
	Invoke(ctx context.Context, req *Req) (*Res, error)
}

// ================== Generic Server Interfaces ==================

// ServerStreamingServer is the server-side interface for server streaming calls.
// The server sends multiple responses for a single request.
type ServerStreamingServer[Req any] interface {
	ServerStream
	// Send sends a typed response to the client.
	Send(ctx context.Context, resp *Req) error
}

// ClientStreamingServer is the server-side interface for client streaming calls.
// The server receives multiple requests and sends a single response.
type ClientStreamingServer[Req, Res any] interface {
	ServerStream
	// Recv receives a typed request from the client.
	Recv(ctx context.Context) (*Req, error)
}

// BidiStreamingServer is the server-side interface for bidirectional streaming calls.
// Both client and server can send multiple messages.
type BidiStreamingServer[Req, Res any] interface {
	ServerStream
	// Send sends a typed response to the client.
	Send(ctx context.Context, resp *Res) error
	// Recv receives a typed request from the client.
	Recv(ctx context.Context) (*Req, error)
}

// UnaryServer is the server-side interface for unary calls (single request/response).
type UnaryServer[Req, Res any] interface {
	ServerStream
	// Recv receives the typed request from the client.
	Recv(ctx context.Context) (*Req, error)
	// Send sends the typed response to the client.
	Send(ctx context.Context, resp *Res) error
}

// ================== Factory Functions ==================

// NewServerStreamingClient creates a typed server streaming client wrapper.
func NewServerStreamingClient[Res any](st ClientStream) ServerStreamingClient[Res] {
	return &serverStreamingClientImpl[Res]{ClientStream: st}
}

// NewClientStreamingClient creates a typed client streaming client wrapper.
func NewClientStreamingClient[Req any](st ClientStream) ClientStreamingClient[Req] {
	return &clientStreamingClientImpl[Req]{ClientStream: st}
}

// NewBidiStreamingClient creates a typed bidirectional streaming client wrapper.
func NewBidiStreamingClient[Req, Res any](st ClientStream) BidiStreamingClient[Req, Res] {
	return &bidiStreamingClientImpl[Req, Res]{ClientStream: st}
}
